import java.util.*;

class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode p = head; p != null; p = p.next) vals.add(p.val);

        // left/right 是 1-based，换算成 0-based 下标
        int i = left - 1, j = right - 1;
        while (i < j) {
            int t = vals.get(i);
            vals.set(i, vals.get(j));
            vals.set(j, t);
            i++;
            j--;
        }

        int idx = 0;
        for (ListNode p = head; p != null; p = p.next) {
            p.val = vals.get(idx++);
        }
        return head;
    }
}

class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;

        // 走到区间的前一个节点
        for (int i = 1; i < left; i++) prev = prev.next;

        // curr 是区间第一个节点，反转后会成为区间尾部
        ListNode curr = prev.next;

        // 头插法：把后面的节点依次插到 prev 后面
        for (int i = 0; i < right - left; i++) {
            ListNode nxt = curr.next;
            curr.next = nxt.next;      // 摘下 nxt
            nxt.next = prev.next;      // nxt 指向原区间头
            prev.next = nxt;           // nxt 接到 prev 后面
        }
        return dummy.next;
    }
}

class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        // 1. 切：找到区间并根据位置摘下来
        ListNode prev = dummy;
        for (int i = 1; i < left; i++) prev = prev.next;
        ListNode start = prev.next;

        ListNode end = start;
        for (int i = 1; i < right - left + 1; i++) end = end.next;
        ListNode after = end.next;
        end.next = null;                      // 断开，区间独立

        // 2. 反：复用第 206 题的标准迭代反转
        ListNode newHead = reverse(start);

        // 3. 接：前接新头，后接剩余段（start 已是区间新尾部）
        prev.next = newHead;
        start.next = after;

        return dummy.next;
    }

    private ListNode reverse(ListNode head) {
        ListNode prev = null, curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}
